and club_id = #{clubId}
and start_date >= #{monthStart} and start_date < #{nextMonthStart}

and (member_id = #{viewerId} or exists (
    select 1 from club_member calendar_member
    where calendar_member.club_id = cms_activity.club_id
      and calendar_member.member_id = #{viewerId}
      and calendar_member.status = 1 and calendar_member.del_flag = 0
))
